 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnClearDsclsType = function () {
    /* sdd-asis-lifecycle:begin fnClearDsclsType — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($('input:checkbox[id=ipt_bfrDsclsType]').is(":checked")) {
