    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnBfrDsclsType
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnBfrDsclsType = async function () {
    /* sdd-asis-lifecycle:begin fnBfrDsclsType — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($('input:checkbox[id=ipt_bfrDsclsType]').is(":checked")) {
        if (await $c.win.confirm("선택한 공시유형이 모두 초기화됩니다.\n진행하시겠습니까?")) {
            $("input[type=checkbox]").removeAttr("checked");
            $('input:checkbox[id=ipt_bfrDsclsType]').attr("checked", "checked");
        } else {
            $('input:checkbox[id=ipt_bfrDsclsType]').removeAttr("checked");
        }
    }
    /* sdd-asis-lifecycle:end */
};
